#include <hip/hip_runtime.h>
#include <torch/extension.h>

#define BM 128
#define BN 128
#define BK 8
#define TM 8
#define TN 8

__global__ void bmm_kernel_opt(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int M, int K, int N) {
    int batch_idx = blockIdx.z;
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    const float* A_batch = A + batch_idx * M * K;
    const float* B_batch = B + batch_idx * K * N;
    float* C_batch = C + batch_idx * M * N;

    __shared__ float sA[BM][BK];
    __shared__ float sB[BK][BN];

    float rC[TM][TN] = {0.0f};

    int tid = ty * 16 + tx;

    // Loading A and B into shared memory
    // tid ranges from 0 to 255.
    // sA is 128x8, total 1024 elements. Each thread needs to load 4 elements.
    // sB is 8x128, total 1024 elements. Each thread needs to load 4 elements.
    int loadA_row = tid / 2;    // 0 to 127
    int loadA_col = tid % 2 * 4; // 0, 4

    int loadB_row = tid / 32;   // 0 to 7
    int loadB_col = tid % 32 * 4; // 0, 4, ..., 124

    for (int k_off = 0; k_off < K; k_off += BK) {
        // Load A into sA
        #pragma unroll
        for (int i = 0; i < 4; i++) {
            if (by * BM + loadA_row < M && k_off + loadA_col + i < K)
                sA[loadA_row][loadA_col + i] = A_batch[(by * BM + loadA_row) * K + (k_off + loadA_col + i)];
            else
                sA[loadA_row][loadA_col + i] = 0.0f;
        }

        // Load B into sB
        #pragma unroll
        for (int i = 0; i < 4; i++) {
            if (k_off + loadB_row < K && bx * BN + loadB_col + i < N)
                sB[loadB_row][loadB_col + i] = B_batch[(k_off + loadB_row) * N + (bx * BN + loadB_col + i)];
            else
                sB[loadB_row][loadB_col + i] = 0.0f;
        }

        __syncthreads();

        // Compute
        #pragma unroll
        for (int k = 0; k < BK; k++) {
            float rA[TM];
            float rB[TN];
            #pragma unroll
            for (int i = 0; i < TM; i++) {
                rA[i] = sA[ty * TM + i][k];
            }
            #pragma unroll
            for (int j = 0; j < TN; j++) {
                rB[j] = sB[k][tx * TN + j];
            }
            #pragma unroll
            for (int i = 0; i < TM; i++) {
                #pragma unroll
                for (int j = 0; j < TN; j++) {
                    rC[i][j] += rA[i] * rB[j];
                }
            }
        }
        __syncthreads();
    }

    // Write out results
    #pragma unroll
    for (int i = 0; i < TM; i++) {
        #pragma unroll
        for (int j = 0; j < TN; j++) {
            int out_row = by * BM + ty * TM + i;
            int out_col = bx * BN + tx * TN + j;
            if (out_row < M && out_col < N) {
                C_batch[out_row * N + out_col] = rC[i][j];
            }
        }
    }
}

