    // sA: 128x8. Threads: 256. Each thread loads 128*8 / 256 = 4 floats.
    // sB: 8x128. Threads: 256. Each thread loads 8*128 / 256 = 4 floats.

    int loadA_row = tid / 2;    // 0 to 127
